<script setup>
import {ref,onMounted,computed} from 'vue';import {RouterLink} from 'vue-router';import AppShell from '../components/AppShell.vue';import {supabase} from '../services/supabase';
const profile=ref(null),jobs=ref([]),applications=ref([]),loading=ref(true);const firstName=computed(()=>profile.value?.full_name?.split(' ')[0]||'there');onMounted(async()=>{const {data:{user}}=await supabase.auth.getUser();const [p,j,a]=await Promise.all([supabase.from('profiles').select('*').eq('id',user.id).maybeSingle(),supabase.from('jobs').select('*').eq('status','active').order('created_at',{ascending:false}).limit(4),supabase.from('applications').select('id,status').eq('student_id',user.id)]);profile.value=p.data;jobs.value=j.data||[];applications.value=a.data||[];loading.value=false})
</script>
<template><AppShell title="Overview" subtitle="Your Campus Gig workspace"><template #default><div class="welcome-banner"><div><span class="eyebrow">YOUR JOURNEY STARTS HERE</span><h1>Hey, {{firstName}} 👋</h1><p>{{profile?.account_type==='employer'?'Find great student talent and grow your team.':'Ready to make your next move? Let’s find work that fits your life.'}}</p><RouterLink :to="profile?.account_type==='employer'?'/post-job':'/jobs'" class="btn btn-gold">{{profile?.account_type==='employer'?'Post a job':'Explore opportunities'}} →</RouterLink></div><div class="banner-symbol">✦</div></div><div class="grid grid-3" style="margin-top:20px"><div class="stat"><strong>{{applications.length}}</strong><span>Applications submitted</span></div><div class="stat"><strong>{{jobs.length}}</strong><span>Fresh opportunities</span></div><div class="stat"><strong>{{profile?.location||'Add location'}}</strong><span>Your preferred area</span></div></div><div class="section-head"><div><span class="eyebrow">HAND-PICKED FOR YOU</span><h2 style="margin:4px 0">Latest opportunities</h2></div><RouterLink to="/jobs" class="muted" style="font-size:13px;font-weight:700">Browse all jobs →</RouterLink></div><div v-if="loading" class="empty">Loading opportunities…</div><div v-else-if="jobs.length" class="grid grid-2"><RouterLink v-for="job in jobs" :key="job.id" :to="`/jobs/${job.id}`" class="card job-card"><div class="job-meta"><span class="badge green">{{job.job_type}}</span><span>{{job.location||'Location flexible'}}</span></div><h3>{{job.title}}</h3><p>{{job.description?.slice(0,125)}}{{job.description?.length>125?'…':''}}</p><div class="job-card-foot"><b>{{job.pay_amount?`R${job.pay_amount}${job.pay_period==='hourly'?'/hr':''}`:'Pay discussed'}}</b><span class="muted">View role →</span></div></RouterLink></div><div v-else class="empty">No jobs have been posted yet. Check back soon.</div><div class="section-head"><div><span class="eyebrow">MAKE IT COUNT</span><h2 style="margin:4px 0">Your next best step</h2></div></div><div class="grid grid-3"><RouterLink to="/profile" class="card quick-card"><span>◌</span><h3>Complete your profile</h3><p>Show employers what you can bring to the table.</p></RouterLink><RouterLink to="/applications" class="card quick-card"><span>▣</span><h3>Track applications</h3><p>Stay up to date with every opportunity you apply for.</p></RouterLink><RouterLink to="/settings" class="card quick-card"><span>⚙</span><h3>Personalise your space</h3><p>Set your preferences, privacy and theme.</p></RouterLink></div></template></AppShell></template>
<style scoped>.welcome-banner{position:relative;overflow:hidden;display:flex;justify-content:space-between;align-items:center;padding:34px 38px;border-radius:20px;background:linear-gradient(115deg,#0d3554,#155879);color:white}.welcome-banner h1{font-size:32px;margin:8px 0}.welcome-banner p{color:#d1e0e9;margin:0 0 20px}.banner-symbol{font-size:150px;color:#ffffff18;line-height:1}.quick-card{transition:.2s}.quick-card:hover{transform:translateY(-3px)}.quick-card>span{font-size:25px;color:var(--green)}.quick-card h3{font-size:16px;margin:13px 0 6px}.quick-card p{font-size:12px;color:var(--muted);line-height:1.6;margin:0}</style>
